(function(){'use strict';const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:2});let config,callback;
const panel=document.createElement('section');panel.className='craft-journal-panel';panel.innerHTML='<label class="refining-check"><input id="craft-with-journals" type="checkbox"> Крафт с журналами</label><div id="craft-journal-fields"></div><p id="craft-journal-summary" class="hint"></p>';document.getElementById('mastery-panel').after(panel);
function render(recipe,cfg,save){config=cfg;callback=save;const list=window.CraftJournalMath.eligible(recipe,window.ECONOMY_DATA),supported=list.length>0;panel.hidden=!['gear','bags'].includes(recipe.kind);$('craft-with-journals').checked=!!cfg.withJournals;$('craft-with-journals').disabled=!supported;if(cfg.withJournals&&supported){const j=list.find(j=>j.id===cfg.journalId)||list[0];cfg.journalId=j.id;$('craft-journal-fields').innerHTML='<label class="field">Журнал<select id="craft-journal-id">'+list.map(j=>'<option value="'+j.id+'">'+esc(window.ECONOMY_DATA.names[j.id]||window.IslandData.journals.find(x=>x.id===j.id)?.name||j.id)+' · T'+recipe.tier+'</option>').join('')+'</select></label><label class="field">Город продажи журналов<select id="craft-journal-city">'+['Bridgewatch','Fort Sterling','Lymhurst','Martlock','Thetford','Caerleon','Brecilien'].map(c=>'<option value="'+c+'">'+c+'</option>').join('')+'</select></label><div class="grid2"><label class="field">Пустой журнал / шт.<input type="number" min="0.01" step="0.01" id="craft-journal-empty" placeholder="Цена из рынка" value="'+(cfg.journalEmptyPrice??'')+'"></label><label class="field">Полный журнал / шт.<input type="number" min="0.01" step="0.01" id="craft-journal-full" placeholder="Цена из рынка" value="'+(cfg.journalFullPrice??'')+'"></label></div>';$('craft-journal-id').value=cfg.journalId;$('craft-journal-city').value=cfg.journalCity||(cfg.sellCity==='Black Market'?cfg.craftCity:cfg.sellCity);}else $('craft-journal-fields').textContent='';$('craft-journal-summary').textContent=supported?'В прибыль добавляется продажа полных книг после комиссий за вычетом пустых. Премиум не увеличивает заполнение.':'Этот рецепт не заполняет ремесленные журналы.';}
panel.onchange=e=>{const keys={'craft-with-journals':'withJournals','craft-journal-id':'journalId','craft-journal-city':'journalCity','craft-journal-empty':'journalEmptyPrice','craft-journal-full':'journalFullPrice'},key=keys[e.target.id];if(!key)return;config[key]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?(e.target.value===''?null:Math.max(0,Number(e.target.value)||0)):e.target.value;callback();};
function result(r){if(!config?.withJournals)return;const j=r.journals;if(!j?.supported)return;$('craft-journal-summary').textContent='Заполнится '+j.count+' журналов; остаток '+fmt(j.remainder)+' славы. '+(j.missing?'Нужны цены журналов.':'Дополнительная прибыль: '+fmt(j.profit)+' серебра. Цена безубыточности товара учитывает этот доход.');}
window.CraftJournalUI={render,result};window.CraftApp.saveConfig({});})();
